-- Jalankan seluruh SQL ini di Supabase > SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(
 id uuid primary key references auth.users(id) on delete cascade,
 full_name text not null default 'Siswa ARABIA',
 role text not null default 'siswa' check(role in('admin','guru','siswa')),
 grade text check(grade in('7','8','9')), created_at timestamptz default now()
);
create table if not exists public.categories(id bigint generated by default as identity primary key,name text not null,description text);
create table if not exists public.levels(id bigint generated by default as identity primary key,name text not null,sort_order int not null default 1,description text);
create table if not exists public.lessons(
 id bigint generated by default as identity primary key,category_id bigint references categories(id),level_id bigint references levels(id),
 title text not null,arabic_title text,description text,content text,xp_reward int not null default 20,
 sort_order int not null default 1,is_published boolean not null default false,created_at timestamptz default now()
);
create table if not exists public.vocabulary(id bigint generated by default as identity primary key,lesson_id bigint references lessons(id) on delete cascade,arabic_word text not null,transliteration text,meaning text not null,image_url text,audio_url text);
create table if not exists public.questions(id bigint generated by default as identity primary key,lesson_id bigint references lessons(id) on delete cascade,question_text text not null,question_type text default 'multiple_choice',explanation text,points int default 10,sort_order int default 1);
create table if not exists public.answers(id bigint generated by default as identity primary key,question_id bigint references questions(id) on delete cascade,answer_text text not null,is_correct boolean default false);
create table if not exists public.lesson_progress(id bigint generated by default as identity primary key,student_id uuid references profiles(id) on delete cascade,lesson_id bigint references lessons(id) on delete cascade,completed boolean default false,score numeric(5,2),completed_at timestamptz,unique(student_id,lesson_id));
create table if not exists public.quiz_attempts(id bigint generated by default as identity primary key,student_id uuid references profiles(id) on delete cascade,lesson_id bigint references lessons(id) on delete cascade,score numeric(5,2) not null,correct_count int not null,total_questions int not null,xp_earned int not null default 0,created_at timestamptz default now());
create table if not exists public.user_answers(id bigint generated by default as identity primary key,attempt_id bigint references quiz_attempts(id) on delete cascade,question_id bigint references questions(id),selected_answer_id bigint references answers(id),is_correct boolean not null);
create table if not exists public.achievements(id bigint generated by default as identity primary key,badge_name text not null,description text,icon text,xp_reward int default 0);
create table if not exists public.user_achievements(id bigint generated by default as identity primary key,student_id uuid references profiles(id) on delete cascade,achievement_id bigint references achievements(id),earned_at timestamptz default now(),unique(student_id,achievement_id));
create table if not exists public.classes(id bigint generated by default as identity primary key,class_name text not null,teacher_id uuid references profiles(id));
create table if not exists public.enrollments(id bigint generated by default as identity primary key,student_id uuid references profiles(id),class_id bigint references classes(id),enrolled_at timestamptz default now(),unique(student_id,class_id));

create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into profiles(id,full_name,grade) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Siswa ARABIA'),new.raw_user_meta_data->>'grade') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists auth_user_profile on auth.users;
create trigger auth_user_profile after insert on auth.users for each row execute procedure public.new_profile();

create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid() $$;
alter table profiles enable row level security;
alter table categories enable row level security; alter table levels enable row level security; alter table lessons enable row level security;
alter table vocabulary enable row level security; alter table questions enable row level security; alter table answers enable row level security;
alter table lesson_progress enable row level security; alter table quiz_attempts enable row level security; alter table user_answers enable row level security;
alter table achievements enable row level security; alter table user_achievements enable row level security; alter table classes enable row level security; alter table enrollments enable row level security;

create policy "profile self or staff read" on profiles for select to authenticated using(id=auth.uid() or my_role() in('admin','guru'));
create policy "profile self update" on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role=(select p.role from profiles p where p.id=auth.uid()));
create policy "categories public read" on categories for select to anon,authenticated using(true);
create policy "levels public read" on levels for select to anon,authenticated using(true);
create policy "published lesson read" on lessons for select to anon,authenticated using(is_published or my_role() in('admin','guru'));
create policy "staff manage lessons" on lessons for all to authenticated using(my_role() in('admin','guru')) with check(my_role() in('admin','guru'));
create policy "vocab read" on vocabulary for select to anon,authenticated using(exists(select 1 from lessons l where l.id=lesson_id and l.is_published) or my_role() in('admin','guru'));
create policy "staff manage vocab" on vocabulary for all to authenticated using(my_role() in('admin','guru')) with check(my_role() in('admin','guru'));
create policy "questions read" on questions for select to anon,authenticated using(exists(select 1 from lessons l where l.id=lesson_id and l.is_published) or my_role() in('admin','guru'));
create policy "staff manage questions" on questions for all to authenticated using(my_role() in('admin','guru')) with check(my_role() in('admin','guru'));
create policy "staff manage answers" on answers for all to authenticated using(my_role() in('admin','guru')) with check(my_role() in('admin','guru'));
create policy "own progress read" on lesson_progress for select to authenticated using(student_id=auth.uid() or my_role() in('admin','guru'));
create policy "staff progress manage" on lesson_progress for all to authenticated using(my_role() in('admin','guru')) with check(my_role() in('admin','guru'));
create policy "own attempts read" on quiz_attempts for select to authenticated using(student_id=auth.uid() or my_role() in('admin','guru'));
create policy "own answers read" on user_answers for select to authenticated using(exists(select 1 from quiz_attempts a where a.id=attempt_id and (a.student_id=auth.uid() or my_role() in('admin','guru'))));
create policy "achievement read" on achievements for select to anon,authenticated using(true);
create policy "own badges read" on user_achievements for select to authenticated using(student_id=auth.uid() or my_role() in('admin','guru'));
create policy "classes read" on classes for select to authenticated using(true);
create policy "staff classes manage" on classes for all to authenticated using(my_role() in('admin','guru')) with check(my_role() in('admin','guru'));
create policy "enrollments read" on enrollments for select to authenticated using(student_id=auth.uid() or my_role() in('admin','guru'));
create policy "staff enrollments manage" on enrollments for all to authenticated using(my_role() in('admin','guru')) with check(my_role() in('admin','guru'));

-- Quiz RPC sends choices only; the correct-answer flag stays in the database.
create or replace function public.get_lesson_quiz(p_lesson_id bigint)
returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'Silakan login.'; end if;
 select jsonb_build_object(
   'lesson', jsonb_build_object('id',l.id,'title',l.title,'description',l.description,'content',l.content,'xp_reward',l.xp_reward),
   'questions', coalesce((
     select jsonb_agg(jsonb_build_object(
       'id',q.id,'question_text',q.question_text,
       'answers',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'answer_text',a.answer_text) order by a.id)
         from public.answers a where a.question_id=q.id),'[]'::jsonb)
     ) order by q.sort_order,q.id)
     from public.questions q where q.lesson_id=l.id
   ),'[]'::jsonb)
 ) into result
 from public.lessons l where l.id=p_lesson_id and l.is_published=true;
 if result is null then raise exception 'Materi tidak tersedia.'; end if;
 return result;
end; $$;
revoke all on function public.get_lesson_quiz(bigint) from public;
grant execute on function public.get_lesson_quiz(bigint) to authenticated;

create or replace function public.submit_lesson_quiz(p_lesson_id bigint,p_answers jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); total int; correct int:=0; scoreval numeric(5,2); xp int; attempt bigint; item jsonb; qid bigint; aid bigint; ok boolean; reward int;
begin
 if uid is null then raise exception 'Silakan login.'; end if;
 if not exists(select 1 from lessons where id=p_lesson_id and is_published) then raise exception 'Materi tidak tersedia.'; end if;
 select count(*) into total from questions where lesson_id=p_lesson_id;
 if total=0 or jsonb_typeof(p_answers)<>'array' or jsonb_array_length(p_answers)<>total then raise exception 'Jawaban belum lengkap atau soal belum tersedia.'; end if;
 select xp_reward into reward from lessons where id=p_lesson_id;
 insert into quiz_attempts(student_id,lesson_id,score,correct_count,total_questions,xp_earned) values(uid,p_lesson_id,0,0,total,0) returning id into attempt;
 for item in select * from jsonb_array_elements(p_answers) loop
  qid:=(item->>'question_id')::bigint; aid:=(item->>'answer_id')::bigint;
  if not exists(select 1 from questions where id=qid and lesson_id=p_lesson_id) then raise exception 'Soal tidak valid.'; end if;
  select is_correct into ok from answers where id=aid and question_id=qid;
  if ok is null then raise exception 'Pilihan tidak valid.'; end if;
  if ok then correct:=correct+1; end if;
  insert into user_answers(attempt_id,question_id,selected_answer_id,is_correct) values(attempt,qid,aid,ok);
 end loop;
 scoreval:=round(correct::numeric/total*100,2);
 xp:=case when correct=total then coalesce(reward,20) else round(correct::numeric/total*coalesce(reward,20))::int end;
 update quiz_attempts set score=scoreval,correct_count=correct,xp_earned=xp where id=attempt;
 insert into lesson_progress(student_id,lesson_id,completed,score,completed_at) values(uid,p_lesson_id,scoreval>=70,scoreval,case when scoreval>=70 then now() end)
 on conflict(student_id,lesson_id) do update set completed=lesson_progress.completed or excluded.completed,score=greatest(coalesce(lesson_progress.score,0),excluded.score),completed_at=coalesce(lesson_progress.completed_at,excluded.completed_at);
 return jsonb_build_object('score',scoreval,'correct_count',correct,'total_questions',total,'xp_earned',xp);
end; $$;
revoke all on function public.submit_lesson_quiz(bigint,jsonb) from public;
grant execute on function public.submit_lesson_quiz(bigint,jsonb) to authenticated;

insert into categories(name,description) select 'Mufradat','Kosakata Bahasa Arab' where not exists(select 1 from categories where name='Mufradat');
insert into levels(name,sort_order,description) select 'Mubtadi (Pemula)',1,'Pengenalan dasar' where not exists(select 1 from levels where sort_order=1);
insert into lessons(category_id,level_id,title,arabic_title,description,content,xp_reward,sort_order,is_published)
select c.id,l.id,'Di sekolah','الْمَدْرَسَةُ','Kenali kosakata di sekolah.','Pelajari arti kata مَدْرَسَةٌ dan kosakata sekolah.',20,1,true from categories c,levels l
where c.name='Mufradat' and l.sort_order=1 and not exists(select 1 from lessons where title='Di sekolah');
insert into questions(lesson_id,question_text,sort_order) select id,'Apa arti kata مَدْرَسَةٌ?',1 from lessons where title='Di sekolah' and not exists(select 1 from questions where lesson_id=lessons.id);
insert into answers(question_id,answer_text,is_correct) select q.id,'Sekolah',true from questions q join lessons l on l.id=q.lesson_id where l.title='Di sekolah' and not exists(select 1 from answers where question_id=q.id);
insert into answers(question_id,answer_text,is_correct) select q.id,'Rumah',false from questions q join lessons l on l.id=q.lesson_id where l.title='Di sekolah' and not exists(select 1 from answers where question_id=q.id and answer_text='Rumah');
insert into answers(question_id,answer_text,is_correct) select q.id,'Pasar',false from questions q join lessons l on l.id=q.lesson_id where l.title='Di sekolah' and not exists(select 1 from answers where question_id=q.id and answer_text='Pasar');
